const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>esc(JSON.stringify(x,null,2));
let entries=[],history=[],cursor=0,currentEntry=null;
const commands=['catalog','show','lookup','check','demand','answers','help'];
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#status').textContent=`${body===undefined?'GET':'POST'} /v0/${path} / HTTP ${r.status}`;return {code:r.status,data:await r.json()};}
const section=(title,body)=>`<h3 class="section-title">${esc(title)}</h3><div class="box">${body}</div>`;
const runButton=(cmd,label)=>`<button data-command="${esc(cmd)}">${esc(label||cmd)}</button>`;
function recorded(status){return status==='recorded'?'<span class="warn">Recorded / not re-run by fvapi</span>':'<span class="good">Real replay</span>';}
function entryView(e){currentEntry=e;return `<h2>${esc(e.title)}</h2><p>${esc(e.claim)}</p><p>${recorded(e.replay.status)} / ${esc(e.kind)}</p>${e.replay.status==='recorded'?'<div class="notice">Recorded stub. Not re-run by fvapi. This transcript comes from an earlier run, not this service.</div>':''}${section('Statements to match',e.statements.map(s=>`<p class="muted">${esc(s.name)} / ${esc(s.file)}:${s.line}</p><pre>${esc(s.text)}</pre>`).join(''))}${section('Proof closure',e.closure.map(f=>`<p>${esc(f.path)} <span class="muted">(${f.bytes} bytes)</span><br><code class="muted">sha256 ${esc(f.sha256)}</code></p>`).join('')+`<a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a>`)}${section('Replay locally',`<pre id="replay-command">${esc(e.replay.command)}</pre><button id="copy-replay">Copy replay command</button><p class="muted">Expected axioms: ${esc(e.replay.expect_axioms.join(', ')||'none')}</p><p>${esc(e.replay.note)}</p>${e.replay.transcript?`<pre>${esc(typeof e.replay.transcript==='string'?e.replay.transcript:JSON.stringify(e.replay.transcript,null,2))}</pre>`:''}`)}${section('Source and licence',`<dl><dt>Toolchain / dependencies</dt><dd>${esc(e.toolchain)} / ${esc(e.requires.join(', '))}</dd><dt>Source</dt><dd>${esc(e.source.repo)} @ ${esc(e.source.commit)}<br>${esc(e.source.paths.join(', '))}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(n=>`${esc(n.name)} / ${esc(n.spdx)} / ${esc(n.source)}`).join('<br>'):'No third-party notices in the manifest.'}</dd></dl>`)}${e.check?runButton('check '+e.id,'Open editable check input'):''}`;}
function catalogView(){return `<h2>Library catalog</h2><p class="muted">${entries.length} entries. Select an id to inspect its claim and proof.</p><div class="table-scroll"><table><thead><tr><th>Entry / claim</th><th>Kind</th><th>Replay</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${runButton('show '+e.id,e.id)}<div class="claim">${esc(e.title)}</div><div class="claim">${esc(e.claim)}</div></td><td>${esc(e.kind)}</td><td>${recorded(e.replay_status)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Try: <code>show ${esc(entries[0]?.id||'ID')}</code></p>`;}
async function checkView(id,reject=false,force=false){let r=await api('catalog/'+encodeURIComponent(id));if(r.code!==200)return errorView(r);currentEntry=r.data;if(!currentEntry.check||force){let result=await api('checks/'+encodeURIComponent(id),{});return `<h2>Check unavailable</h2><div class="notice">HTTP ${result.code}: ${esc(result.data.detail)}. Choose a checker from the catalog.</div>${runButton('catalog','Browse catalog')}`;}let input=structuredClone(currentEntry.check.example_input);if(reject&&input.rows?.[0]?.weights)input.rows[0].weights[0]+=1;let html=`<h2>Check ${esc(id)}</h2><p class="muted">Edit the JSON, then run the checker. A server verdict still needs a local re-check.</p><label for="check-input">Input JSON</label><br><textarea id="check-input" spellcheck="false">${json(input)}</textarea><div class="actions"><button id="run-check">Run check</button><button id="reset-input">Restore example</button></div><div id="check-result"></div>`;return html;}
function errorView(r){return `<div class="notice">HTTP ${r.code}: ${esc(r.data.detail||r.data.error)}. Try another id or open the catalog.</div>`;}
async function execute(command){command=command.trim();if(!command)return;history.push(command);cursor=history.length;$('#command').value='';$('#completions').textContent='';$('#output').innerHTML=`<div class="echo">founder@vflab $ <strong>${esc(command)}</strong></div><p class="muted">Waiting for API…</p>`;try{const [verb,...args]=command.split(/\s+/);let html='';if(verb==='catalog'){let r=await api('catalog');entries=r.data.entries;html=catalogView();}else if(verb==='show'){let r=await api('catalog/'+encodeURIComponent(args[0]||''));html=r.code===200?entryView(r.data):errorView(r);}else if(verb==='lookup'){let key=args[0]==='--sha256'?'artifact_sha256':args[0]==='--statement'?'statement':'spec_id';let value=args[0]?.startsWith('--')?args.slice(1).join(' '):args.join(' ');let r=await api('lookup',{[key]:value});html=r.code===200?`<p class="good">Match found / ${esc(r.data.answer_id)} / matched on ${esc(r.data.matched_on)}</p>${entryView(r.data.entry)}`:r.code===404?`<h2>No library match</h2><div class="notice">Logged as demand (${esc(r.data.miss_id)}). No agent works on single requests.</div><p>${esc(r.data.detail)}</p>${runButton('demand','Read demand log')}`:errorView(r);}else if(verb==='check'){html=await checkView(args[0]||entries.find(e=>e.kind==='checker')?.id||'',args.includes('--reject'),args.includes('--force'));}else if(verb==='demand'){let {data:d}=await api('demand');html=`<h2>Demand log</h2><p class="muted">Misses reveal what the library cannot answer. No request-time LLM.</p>${section('Counts by key',d.by_key.length?d.by_key.map(k=>`<p class="break"><span class="good">${k.count}</span> ${esc(k.key)}</p>`).join(''):'<p>No misses yet. Run a lookup to test a specification.</p>')}${section('Misses / newest first',`<pre>${json(d.misses)}</pre>`)}`;}else if(verb==='answers'){let {data:d}=await api('answers');html=`<h2>Answer log</h2><p class="muted">Library matches and checker results. Re-check delivered proofs locally.</p>${d.answers.length?`<div class="table-scroll"><table><thead><tr><th>Answer / time</th><th>Entry</th><th>Outcome</th></tr></thead><tbody>${d.answers.map(a=>`<tr><td>${esc(a.answer_id)}<br><span class="muted">${esc(a.at)}</span></td><td>${runButton('show '+a.entry_id,a.entry_id)}</td><td>${esc(a.verdict||a.kind)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No answers yet. Look up a specification to start.</p>'}`;}else if(verb==='help'){html=`<h2>A small shell for the proof library</h2><pre>catalog                     Browse all entries\nshow ID                     Read a claim and its proof closure\nlookup --spec ID            Look up a specification\nlookup --sha256 HASH        Match an artifact\nlookup --statement TEXT     Match a statement\ncheck ID                    Edit input and run a checker\ndemand                      Read misses and their counts\nanswers                     Read delivered answers\nhelp                        Read these commands</pre><p class="muted">Tab completes commands and entry ids. Up and Down recall this session's commands. Select an id anywhere to inspect it.</p>`;}else html=`<div class="notice">Unknown command: ${esc(verb)}. Type help to see the available commands.</div>`;$('#output').innerHTML=`<div class="echo">founder@vflab $ <strong>${esc(command)}</strong></div>${html}`;$('#buffer').scrollTop=0;wireCheck();if(args.includes('--reject')||args.includes('--accept'))await submitCheck();document.body.dataset.ready='true';}catch(e){$('#output').innerHTML=`<div class="notice">The API request failed. Check the connection and run the command again. ${esc(e.message)}</div>`;document.body.dataset.ready='true';}}
function wireCheck(){if($('#run-check'))$('#run-check').onclick=submitCheck;if($('#reset-input'))$('#reset-input').onclick=()=>{$('#check-input').value=JSON.stringify(currentEntry.check.example_input,null,2);$('#check-result').textContent='';};if($('#copy-replay'))$('#copy-replay').onclick=async()=>{try{await navigator.clipboard.writeText(currentEntry.replay.command);$('#copy-replay').textContent='Copied replay command';}catch{$('#copy-replay').textContent='Select the command above to copy it';}};}
async function submitCheck(){if(!$('#check-input'))return;try{let input=JSON.parse($('#check-input').value),r=await api('checks/'+encodeURIComponent(currentEntry.id),input);$('#check-result').innerHTML=r.code===200?section('Checker result',`<h2 class="${r.data.verdict==='accept'?'good':'warn'}">${esc(r.data.verdict==='accept'?'Accepted':'Rejected')}</h2><p>Exit ${r.data.exit_code} / ${r.data.elapsed_ms} ms / ${esc(r.data.ran_on)}</p><pre>${json(r.data.output)}</pre><p class="muted">Re-check locally:</p><pre>${esc(r.data.recheck.command)}</pre><p class="break muted">Input sha256 ${esc(r.data.input_sha256)}</p>`):errorView(r);}catch(e){$('#check-result').innerHTML=`<div class="notice">The input is not valid JSON, or the request failed. Fix the input and try again. ${esc(e.message)}</div>`;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(b)execute(b.dataset.command);});$('#command-form').onsubmit=e=>{e.preventDefault();execute($('#command').value);};$('#command').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();cursor=Math.max(0,Math.min(history.length,cursor+(e.key==='ArrowUp'?-1:1)));$('#command').value=history[cursor]||'';}if(e.key==='Tab'){e.preventDefault();let value=$('#command').value,parts=value.split(/\s+/),last=parts.pop(),pool=parts.length?entries.map(e=>e.id):commands,matches=pool.filter(x=>x.startsWith(last));if(matches.length===1)$('#command').value=[...parts,matches[0]].join(' ');$('#completions').textContent=matches.join('  ');}};
(async()=>{try{let [h,c]=await Promise.all([api('health'),api('catalog')]);entries=c.data.entries;$('#health').textContent='● API connected / prototype';}catch{$('#health').textContent='API unavailable';}const state=new URLSearchParams(location.search).get('state')||'catalog';const first=entries.find(e=>e.kind==='checker')?.id||'vf.contrast-2x2',stub=entries.find(e=>e.replay_status==='recorded'&&e.id.includes('glm'))?.id||entries.find(e=>e.replay_status==='recorded')?.id;let initial={catalog:'catalog',entry:'show '+first,recorded:'show '+stub,'lookup-hit':'lookup --spec '+first,'lookup-miss':'lookup --spec missing.example','check-accept':'check '+first+' --accept','check-reject':'check '+first+' --reject','check-409':'check '+stub+' --force',demand:'demand',answers:'answers',mobile:'catalog'}[state]||'help';await execute(initial);})();
